#include <stdio.h>
#include <string.h>
#include <thinkthen.h>

thinkthen_engine *tt = thinkthen_engine_new();

/* rank answers with the places in order: 2, the outage;
   4, the Friday quote; 3, the bill due in a month; and 1,
   the newsletter, last */
const char *rank = "{\"decide\": \"Does this need an answer today?\", "
    "\"rank\": true, "
    "\"records\": [\"Newsletter: our autumn catalog is here. No reply needed.\", "
    "\"Our checkout page is down and customers cannot pay\", "
    "\"Reminder: your invoice is due in 30 days\", "
    "\"Please send the signed quote by Friday\"]}";
char *ranked = thinkthen_call(tt, rank);
puts(ranked ? ranked : thinkthen_error_message(tt));
thinkthen_free_string(ranked);
